from itertools import combinations

def find_golomb_ruler(n):
    for i in range(1, 10000):
        ruler = [0, i]
        for j in range(2, n):
            for k in range(ruler[-1] + 1, 10000):
                distances = set()
                for x, y in combinations(ruler + [k], 2):
                    distances.add(abs(x - y))
                if len(distances) == len(ruler + [k]) * (len(ruler + [k]) - 1) // 2:
                    ruler.append(k)
                    break
            else:
                break
        else:
            return ruler
    return "UNSATISFIABLE"

print(find_golomb_ruler(11))
